-- Hand-written migration.sql.
--
-- This should normally be generated by `prisma migrate dev`. In this
-- environment the Prisma schema-engine binary cannot be executed (blocked by
-- an OS-level policy on spawning newly-downloaded native binaries), so this
-- file was authored by hand to exactly match prisma/schema.prisma. Once the
-- policy is resolved, verify this file with `prisma migrate diff
-- --from-migrations prisma/migrations --to-schema-datamodel prisma/schema.prisma --script`
-- and reconcile any drift before trusting `prisma migrate dev` again.

CREATE TYPE "WorkspaceRole" AS ENUM ('owner', 'member');
CREATE TYPE "DealStage" AS ENUM ('first_contact', 'after_demo', 'proposal_sent', 'closing', 'lost', 'won');
CREATE TYPE "AgentRunStatus" AS ENUM ('succeeded', 'failed', 'validation_error');
CREATE TYPE "ModelClass" AS ENUM ('FAST', 'BALANCED', 'DEEP_REASONING');
CREATE TYPE "AgentScope" AS ENUM ('prospect', 'deal', 'workspace', 'conversational');

CREATE TABLE "user" (
    "id" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "name" TEXT,
    "password_hash" TEXT NOT NULL,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "user_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "user_email_key" ON "user"("email");

CREATE TABLE "workspace" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "workspace_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "workspace_context" (
    "id" TEXT NOT NULL,
    "workspace_id" TEXT NOT NULL,
    "offer_description" TEXT NOT NULL,
    "icp_description" TEXT NOT NULL,
    "tone" TEXT NOT NULL,
    "pricing_summary" TEXT,
    "version" INTEGER NOT NULL,
    "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "workspace_context_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "workspace_context_workspace_id_fkey" FOREIGN KEY ("workspace_id") REFERENCES "workspace"("id") ON DELETE CASCADE
);
CREATE INDEX "workspace_context_workspace_id_idx" ON "workspace_context"("workspace_id");
CREATE UNIQUE INDEX "workspace_context_workspace_id_version_key" ON "workspace_context"("workspace_id", "version");

CREATE TABLE "workspace_member" (
    "id" TEXT NOT NULL,
    "workspace_id" TEXT NOT NULL,
    "user_id" TEXT NOT NULL,
    "role" "WorkspaceRole" NOT NULL,
    CONSTRAINT "workspace_member_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "workspace_member_workspace_id_fkey" FOREIGN KEY ("workspace_id") REFERENCES "workspace"("id") ON DELETE CASCADE,
    CONSTRAINT "workspace_member_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "user"("id") ON DELETE CASCADE
);
CREATE INDEX "workspace_member_workspace_id_idx" ON "workspace_member"("workspace_id");
CREATE UNIQUE INDEX "workspace_member_workspace_id_user_id_key" ON "workspace_member"("workspace_id", "user_id");

CREATE TABLE "prospect" (
    "id" TEXT NOT NULL,
    "workspace_id" TEXT NOT NULL,
    "full_name" TEXT NOT NULL,
    "company" TEXT,
    "role_title" TEXT,
    "raw_notes" TEXT,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "prospect_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "prospect_workspace_id_fkey" FOREIGN KEY ("workspace_id") REFERENCES "workspace"("id") ON DELETE CASCADE
);
CREATE INDEX "prospect_workspace_id_idx" ON "prospect"("workspace_id");

CREATE TABLE "deal" (
    "id" TEXT NOT NULL,
    "workspace_id" TEXT NOT NULL,
    "prospect_id" TEXT NOT NULL,
    "stage" "DealStage" NOT NULL,
    "estimated_amount" DECIMAL(65,30),
    "last_action_at" TIMESTAMP(3),
    CONSTRAINT "deal_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "deal_workspace_id_fkey" FOREIGN KEY ("workspace_id") REFERENCES "workspace"("id") ON DELETE CASCADE,
    CONSTRAINT "deal_prospect_id_fkey" FOREIGN KEY ("prospect_id") REFERENCES "prospect"("id") ON DELETE CASCADE
);
CREATE INDEX "deal_workspace_id_idx" ON "deal"("workspace_id");
CREATE INDEX "deal_prospect_id_idx" ON "deal"("prospect_id");

CREATE TABLE "deal_stage_event" (
    "id" TEXT NOT NULL,
    "deal_id" TEXT NOT NULL,
    "from_stage" "DealStage",
    "to_stage" "DealStage" NOT NULL,
    "occurred_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "deal_stage_event_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "deal_stage_event_deal_id_fkey" FOREIGN KEY ("deal_id") REFERENCES "deal"("id") ON DELETE CASCADE
);
CREATE INDEX "deal_stage_event_deal_id_idx" ON "deal_stage_event"("deal_id");

CREATE TABLE "agent" (
    "id" TEXT NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "function_id" TEXT NOT NULL,
    "model_class" "ModelClass" NOT NULL,
    "scope" "AgentScope" NOT NULL,
    CONSTRAINT "agent_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "agent_code_key" ON "agent"("code");

CREATE TABLE "agent_prompt_version" (
    "id" TEXT NOT NULL,
    "agent_id" TEXT NOT NULL,
    "version_number" INTEGER NOT NULL,
    "template" TEXT NOT NULL,
    "input_schema" JSONB NOT NULL,
    "output_schema" JSONB NOT NULL,
    "is_active" BOOLEAN NOT NULL DEFAULT false,
    CONSTRAINT "agent_prompt_version_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "agent_prompt_version_agent_id_fkey" FOREIGN KEY ("agent_id") REFERENCES "agent"("id") ON DELETE CASCADE
);
CREATE INDEX "agent_prompt_version_agent_id_idx" ON "agent_prompt_version"("agent_id");
CREATE UNIQUE INDEX "agent_prompt_version_agent_id_version_number_key" ON "agent_prompt_version"("agent_id", "version_number");

CREATE TABLE "agent_run" (
    "id" TEXT NOT NULL,
    "workspace_id" TEXT NOT NULL,
    "agent_prompt_version_id" TEXT NOT NULL,
    "prospect_id" TEXT,
    "deal_id" TEXT,
    "triggered_by_user_id" TEXT NOT NULL,
    "input_payload" JSONB NOT NULL,
    "output_payload" JSONB,
    "model_used" TEXT NOT NULL,
    "tokens_in" INTEGER,
    "tokens_out" INTEGER,
    "estimated_cost" DECIMAL(65,30),
    "status" "AgentRunStatus" NOT NULL,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "agent_run_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "agent_run_workspace_id_fkey" FOREIGN KEY ("workspace_id") REFERENCES "workspace"("id") ON DELETE CASCADE,
    CONSTRAINT "agent_run_agent_prompt_version_id_fkey" FOREIGN KEY ("agent_prompt_version_id") REFERENCES "agent_prompt_version"("id"),
    CONSTRAINT "agent_run_prospect_id_fkey" FOREIGN KEY ("prospect_id") REFERENCES "prospect"("id"),
    CONSTRAINT "agent_run_deal_id_fkey" FOREIGN KEY ("deal_id") REFERENCES "deal"("id"),
    CONSTRAINT "agent_run_triggered_by_user_id_fkey" FOREIGN KEY ("triggered_by_user_id") REFERENCES "user"("id")
);
CREATE INDEX "agent_run_workspace_id_idx" ON "agent_run"("workspace_id");
CREATE INDEX "agent_run_prospect_id_idx" ON "agent_run"("prospect_id");
CREATE INDEX "agent_run_deal_id_idx" ON "agent_run"("deal_id");
